// Generated by scripts/sync-website-demos.mjs from the website tool pages. Edit the website copy and re-run.
/** A copy of the extension’s colour engine, so demo numbers match what the tools print. */
export interface Rgb {
  r: number
  g: number
  b: number
}

const clamp = (value: number, min: number, max: number) => Math.min(max, Math.max(min, value))
const round = Math.round

export function hexToRgb(hex: string): Rgb {
  const raw = hex.replace('#', '')
  return {
    r: parseInt(raw.slice(0, 2), 16),
    g: parseInt(raw.slice(2, 4), 16),
    b: parseInt(raw.slice(4, 6), 16),
  }
}

export function rgbToHex({ r, g, b }: Rgb) {
  return `#${[r, g, b].map((channel) => clamp(round(channel), 0, 255).toString(16).padStart(2, '0')).join('')}`
}

function hue(rn: number, gn: number, bn: number, max: number, delta: number) {
  if (delta === 0) return 0
  if (max === rn) return 60 * (((gn - bn) / delta) % 6)
  if (max === gn) return 60 * ((bn - rn) / delta + 2)
  return 60 * ((rn - gn) / delta + 4)
}

export function rgbToHsl({ r, g, b }: Rgb) {
  const [rn, gn, bn] = [r / 255, g / 255, b / 255]
  const max = Math.max(rn, gn, bn)
  const min = Math.min(rn, gn, bn)
  const delta = max - min
  const l = (max + min) / 2
  const s = delta === 0 ? 0 : delta / (1 - Math.abs(2 * l - 1))
  return {
    h: round((hue(rn, gn, bn, max, delta) + 360) % 360),
    s: round(s * 100),
    l: round(l * 100),
  }
}

export function hslToRgb({ h, s, l }: { h: number; s: number; l: number }): Rgb {
  const sn = clamp(s, 0, 100) / 100
  const ln = clamp(l, 0, 100) / 100
  const c = (1 - Math.abs(2 * ln - 1)) * sn
  const hp = (((h % 360) + 360) % 360) / 60
  const x = c * (1 - Math.abs((hp % 2) - 1))
  const segment = Math.min(Math.floor(hp), 5)
  const table: [number, number, number][] = [
    [c, x, 0],
    [x, c, 0],
    [0, c, x],
    [0, x, c],
    [x, 0, c],
    [c, 0, x],
  ]
  const [rn, gn, bn] = table[segment]
  const m = ln - c / 2
  return { r: round((rn + m) * 255), g: round((gn + m) * 255), b: round((bn + m) * 255) }
}

export function rgbToHsv({ r, g, b }: Rgb) {
  const [rn, gn, bn] = [r / 255, g / 255, b / 255]
  const max = Math.max(rn, gn, bn)
  const delta = max - Math.min(rn, gn, bn)
  return {
    h: round((hue(rn, gn, bn, max, delta) + 360) % 360),
    s: max === 0 ? 0 : round((delta / max) * 100),
    v: round(max * 100),
  }
}

export function rgbToHwb(rgb: Rgb) {
  const { h } = rgbToHsv(rgb)
  return {
    h,
    w: round((Math.min(rgb.r, rgb.g, rgb.b) / 255) * 100),
    b: round((1 - Math.max(rgb.r, rgb.g, rgb.b) / 255) * 100),
  }
}

export function rgbToCmyk({ r, g, b }: Rgb) {
  const [rn, gn, bn] = [r / 255, g / 255, b / 255]
  const k = 1 - Math.max(rn, gn, bn)
  if (k === 1) return { c: 0, m: 0, y: 0, k: 100 }
  return {
    c: round(((1 - rn - k) / (1 - k)) * 100),
    m: round(((1 - gn - k) / (1 - k)) * 100),
    y: round(((1 - bn - k) / (1 - k)) * 100),
    k: round(k * 100),
  }
}

/** The six rows the Color Converter prints, in its order and syntax. */
export function formats(hex: string) {
  const rgb = hexToRgb(hex)
  const hsl = rgbToHsl(rgb)
  const hsv = rgbToHsv(rgb)
  const hwb = rgbToHwb(rgb)
  const cmyk = rgbToCmyk(rgb)
  return [
    { label: 'HEX', value: rgbToHex(rgb) },
    { label: 'RGB', value: `rgb(${rgb.r}, ${rgb.g}, ${rgb.b})` },
    { label: 'HSL', value: `hsl(${hsl.h}, ${hsl.s}%, ${hsl.l}%)` },
    { label: 'HSV', value: `hsv(${hsv.h}, ${hsv.s}%, ${hsv.v}%)` },
    { label: 'HWB', value: `hwb(${hwb.h} ${hwb.w}% ${hwb.b}%)` },
    { label: 'CMYK', value: `cmyk(${cmyk.c}%, ${cmyk.m}%, ${cmyk.y}%, ${cmyk.k}%)` },
  ]
}

function linear(channel: number) {
  const normalized = channel / 255
  return normalized <= 0.04045 ? normalized / 12.92 : Math.pow((normalized + 0.055) / 1.055, 2.4)
}

const luminance = ({ r, g, b }: Rgb) => 0.2126 * linear(r) + 0.7152 * linear(g) + 0.0722 * linear(b)

export function contrast(foreground: string, background: string) {
  const a = luminance(hexToRgb(foreground))
  const b = luminance(hexToRgb(background))
  const ratio = Math.round(((Math.max(a, b) + 0.05) / (Math.min(a, b) + 0.05)) * 100) / 100
  return {
    ratio,
    aaNormal: ratio >= 4.5,
    aaLarge: ratio >= 3,
    aaaNormal: ratio >= 7,
    aaaLarge: ratio >= 4.5,
  }
}

export interface Oklch {
  l: number
  c: number
  h: number
}

function linearToChannel(value: number) {
  const v = value <= 0.0031308 ? 12.92 * value : 1.055 * Math.pow(value, 1 / 2.4) - 0.055
  return v * 255
}

export function rgbToOklch({ r, g, b }: Rgb): Oklch {
  const [lr, lg, lb] = [linear(r), linear(g), linear(b)]
  const l = Math.cbrt(0.4122214708 * lr + 0.5363325363 * lg + 0.0514459929 * lb)
  const m = Math.cbrt(0.2119034982 * lr + 0.6806995451 * lg + 0.1073969566 * lb)
  const s = Math.cbrt(0.0883024619 * lr + 0.2817188376 * lg + 0.6299787005 * lb)
  const L = 0.2104542553 * l + 0.793617785 * m - 0.0040720468 * s
  const A = 1.9779984951 * l - 2.428592205 * m + 0.4505937099 * s
  const B = 0.0259040371 * l + 0.7827717662 * m - 0.808675766 * s
  const c = Math.sqrt(A * A + B * B)
  const h = c < 1e-4 ? 0 : ((Math.atan2(B, A) * 180) / Math.PI + 360) % 360
  return { l: L, c, h }
}

function oklchToLinear({ l, c, h }: Oklch): [number, number, number] {
  const rad = (h * Math.PI) / 180
  const A = c * Math.cos(rad)
  const B = c * Math.sin(rad)
  const l_ = Math.pow(l + 0.3963377774 * A + 0.2158037573 * B, 3)
  const m_ = Math.pow(l - 0.1055613458 * A - 0.0638541728 * B, 3)
  const s_ = Math.pow(l - 0.0894841775 * A - 1.291485548 * B, 3)
  return [
    4.0767416621 * l_ - 3.3077115913 * m_ + 0.2309699292 * s_,
    -1.2684380046 * l_ + 2.6097574011 * m_ - 0.3413193965 * s_,
    -0.0041960863 * l_ - 0.7034186147 * m_ + 1.707614701 * s_,
  ]
}

const inGamut = (channels: [number, number, number]) =>
  channels.every((v) => v >= -1e-4 && v <= 1 + 1e-4)

/** Lowers chroma until the colour fits sRGB, keeping hue and lightness. */
export function oklchToRgb(color: Oklch): Rgb {
  let channels = oklchToLinear(color)
  if (!inGamut(channels)) {
    let low = 0
    let high = color.c
    for (let step = 0; step < 18; step += 1) {
      const mid = (low + high) / 2
      if (inGamut(oklchToLinear({ ...color, c: mid }))) low = mid
      else high = mid
    }
    channels = oklchToLinear({ ...color, c: low })
  }
  const [r, g, b] = channels.map((v) => clamp(round(linearToChannel(clamp(v, 0, 1))), 0, 255))
  return { r, g, b }
}
